      const countermeasureProgress = calculateCountermeasureProgress(internalInput);
  
      const now = internalInput.currentDateTime || new Date();
      const elapsedDays = Math.floor(
        (now.getTime() - internalInput.planStartDate.getTime()) / (1000 * 60 * 60 * 24)
      );
  
      let reportContent = buildReportContent('improving', '順調', filteredDataPoints, internalInput.teamId);
  
