const __aivicBundle_5_calculateIssueResolutionSpeed = (() => {
  interface IssueResolutionSpeedInput {
    issues: Array<{
      issueId?: string;
      reportedDate: Date | string;
      resolvedDate: Date | string | null;
      status: 'open' | 'resolved' | 'closed';
    }>;
    aggregationPeriodStart: Date | string;
    aggregationPeriodEnd: Date | string;
    teamId: string;
  }
  
  interface IssueResolutionSpeedResult {
    averageResolutionDays: number;
    resolvedIssueCount: number;
    openIssueCount: number;
    resolutionSpeedByIssue: Array<{
      issueId: string;
      resolutionDays: number | null;
    }>;
    calculatedAt: Date;
  }
  
   function calculateIssueResolutionSpeed(
    input: IssueResolutionSpeedInput
  ): IssueResolutionSpeedResult {
    if (input["teamId"] === undefined || input["teamId"] === null) { throw new Error("teamId is required"); }
    const periodStart = new Date(input.aggregationPeriodStart);
    const periodEnd = new Date(input.aggregationPeriodEnd);
    const calculatedAt = new Date();
  
    const resolutionSpeedByIssue: Array<{
      issueId: string;
      resolutionDays: number | null;
    }> = [];
  
    let resolvedIssueCount = 0;
    let openIssueCount = 0;
    let totalResolutionDays = 0;
  
    for (const issue of input.issues) {
      const reportedDate = new Date(issue.reportedDate);
  
      // フィルタ: 集計期間内に報告された課題のみ対象
      if (reportedDate < periodStart || reportedDate > periodEnd) {
        continue;
      }
  
      const issueId = issue.issueId || `issue-${randomUUID()}`;
  
      if (issue.status === 'resolved' && issue.resolvedDate !== null) {
        const resolvedDate = new Date(issue.resolvedDate);
        const resolutionDays = Math.ceil(
          (resolvedDate.getTime() - reportedDate.getTime()) / (1000 * 60 * 60 * 24)
        );
  
        resolutionSpeedByIssue.push({
          issueId,
          resolutionDays,
        });
  
        totalResolutionDays += resolutionDays;
        resolvedIssueCount++;
      } else if (issue.status === 'open') {
        resolutionSpeedByIssue.push({
          issueId,
          resolutionDays: null,
        });
  
        openIssueCount++;
      } else if (issue.status === 'closed' && issue.resolvedDate !== null) {
        const resolvedDate = new Date(issue.resolvedDate);
        const resolutionDays = Math.ceil(
          (resolvedDate.getTime() - reportedDate.getTime()) / (1000 * 60 * 60 * 24)
        );
  
        resolutionSpeedByIssue.push({
          issueId,
          resolutionDays,
        });
  
        totalResolutionDays += resolutionDays;
        resolvedIssueCount++;
      }
    }
  
    const averageResolutionDays =
      resolvedIssueCount > 0 ? totalResolutionDays / resolvedIssueCount : 0;
  
    return {
      averageResolutionDays,
      resolvedIssueCount,
      openIssueCount,
      resolutionSpeedByIssue,
      calculatedAt,
    };
  }
  return { calculateIssueResolutionSpeed };
})();
